tosedo addBig(a, b)
    sheye res <- [];
    sheye i <- 0;
    sheye carry <- 0;
    sheye la <- louwo(a);
    sheye lb <- louwo(b);
    sheye da <- 0;
    sheye db <- 0;
    sheye s <- 0;
    veshim (((i < la) emsoulve (i < lb)) emsoulve (carry > 0)) {
        da <- 0;
        db <- 0;
