            cur <- 0;
            wesosa (idx < louwo(res)) {
                cur <- res[idx];
            }
            p <- cur + carry;
            wesosa (idx < louwo(res)) {
                res[idx] <- p drossou 10;
            } oli {
                omse(res, p drossou 10);
            }
